<?php include __DIR__.'/_head.php'; ?><h1>Transactions & Reconciliation</h1><div class="warn">Attempts stay <b>PENDING</b> for up to <?=e($pending_days)?> days unless confirmed earlier. Then unverified attempts become EXPIRED.</div><div class="card"><form class="row"><select name="period"><?php foreach(['day','week','month','custom'] as $x):?><option value="<?=$x?>" <?=$period===$x?'selected':''?>><?=ucfirst($x)?></option><?php endforeach;?></select><select name="status"><option value="">All status</option><?php foreach(['SUCCESS','PENDING','FAILED','EXPIRED'] as $x):?><option <?=$status===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><select name="bank_id"><option value="">All banks</option><?php foreach($banks as $b):?><option value="<?=e($b['id'])?>" <?=(string)$bank_id===(string)$b['id']?'selected':''?>><?=e($b['bank_name'])?></option><?php endforeach;?></select><input type="date" name="start" value="<?=e($start)?>"><input type="date" name="end" value="<?=e($end)?>"><button>Apply</button><a class="btn btn2" href="<?=e(url('/admin/reconciliation.csv').'?'.http_build_query(['period'=>$period,'status'=>$status,'bank_id'=>$bank_id,'start'=>$start,'end'=>$end]))?>">Export CSV</a></form><p class="big">Confirmed total: ₹<?=amount_fmt($total)?></p></div><div class="card"><h2>Manual Cross-Check</h2><form method="post" action="<?=e(url('/admin/manual-confirm'))?>" class="row"><?=csrf_field()?><select name="bank_id" required><?php foreach($banks as $b):?><option value="<?=e($b['id'])?>"><?=e($b['bank_name'])?></option><?php endforeach;?></select><input class="grow" name="reference" placeholder="YEEDIPAY Ref OR Customer UTR/RRN" required><select name="status"><?php foreach(['SUCCESS','FAILED','PENDING','EXPIRED'] as $x):?><option><?=$x?></option><?php endforeach;?></select><input name="amount" placeholder="Confirmed amount"><input name="upi_txn_id" placeholder="UPI Txn ID"><input name="rrn" placeholder="RRN/UTR"><input name="payer_vpa" placeholder="Payer VPA"><button>Update</button></form></div><div class="card"><h2>Bulk Bank CSV</h2><form method="post" action="<?=e(url('/admin/reconcile'))?>" enctype="multipart/form-data" class="row"><?=csrf_field()?><select name="bank_id" required><?php foreach($banks as $b):?><option value="<?=e($b['id'])?>"><?=e($b['bank_name'])?></option><?php endforeach;?></select><input type="file" name="file" accept=".csv" required><button>Import & Match</button></form><p class="muted">CSV needs status + one of: reference, customer_utr/utr, rrn, upi_txn_id. Optional: amount,payer_vpa.</p></div><div class="card scroll"><table><tr><th>Date (IST)</th><th>Customer</th><th>Bank</th><th>Reference</th><th>Status</th><th>Requested</th><th>Confirmed</th><th>Customer UTR</th><th>UPI Txn</th><th>RRN</th><th>Limit</th><th>Source</th></tr><?php foreach($txns as $t):?><tr><td><?=e(format_datetime_ist((string)($t['created_at'] ?? '')))?></td><td><?=e($t['customer_code'].' / '.$t['customer_name'])?></td><td><?=e($t['bank_name'])?></td><td class="mono"><?=e($t['reference'])?></td><td class="status-<?=e($t['status'])?>"><?=e($t['status'])?></td><td><?=e($t['requested_amount']??'')?></td><td><?=e($t['confirmed_amount']??'')?></td><td><?=e($t['customer_reported_utr']??'')?></td><td><?=e($t['upi_txn_id']??'')?></td><td><?=e($t['rrn']??'')?></td><td><?=((int)$t['limit_breach']?'REVIEW: '.e($t['limit_note']):'')?></td><td><?=e($t['confirmation_source']??'')?></td></tr><?php endforeach;?></table></div><?php include __DIR__.'/_foot.php'; ?>